import { useAuth } from "@/_core/hooks/useAuth";
import { useEffect, useMemo, useState } from "react";
import { startLogin } from "@/const";
import { trpc } from "@/lib/trpc";
import { BrandLogo } from "@/components/BrandLogo";
import { formatReportEmailSentAt } from "@shared/emailStatus";
import { roleLensOptions, type RoleLens } from "@shared/assessment";
import type { CareerPathReport } from "@shared/careerPath";
import { AlertCircle, ArrowLeft, CheckCircle2, Clock3, Download, FileText, LockKeyhole, Loader2, Mail, MailCheck, MailWarning, RefreshCw, ShieldCheck } from "lucide-react";
import { Link } from "wouter";
import { toast } from "sonner";
import { LineChart, Line, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { buildSubPathwayComparisonSvg, svgToDownloadUrl } from "@shared/reportComparisonVisual";
import { reportComparisonPreview, reportComparisonPreviewHistory } from "@shared/reportComparisonFixture";
import { svgToPngBlob, triggerDownload } from "@/lib/visualDownload";
import { isQaFixtureEnabled, QA_FIXTURE_STORAGE_KEY } from "@shared/qaFixture";
import { courseCatalog, COURSE_PRICE_KES, COURSE_STAGE_AMOUNT_KES } from "@shared/courseCatalog";
import { buildCourseCompletionShareSvg } from "@shared/courseCompletionVisual";
import { CoachingVisualPreview } from "@/components/CoachingVisualPreview";
import { summarizeCourseEnrollment } from "@shared/coursePaymentRollup";

export default function UserDashboard() {
  const { user, loading: authLoading, logout } = useAuth();
  const history = trpc.dashboard.mine.useQuery(undefined, { enabled: Boolean(user), retry: false });
  const recommendations = trpc.dashboard.recommendations.useQuery(undefined, { enabled: Boolean(user), retry: false });
  const profile = trpc.profile.get.useQuery(undefined, { enabled: Boolean(user), retry: false });
  const [activityFilter, setActivityFilter] = useState<"all" | "completed" | "unlocked">("all");
  const [activityLimit, setActivityLimit] = useState(4);
  const [profileModalOpen, setProfileModalOpen] = useState(false);
  const careerPathHistory = trpc.careerPath.history.useQuery(undefined, { enabled: Boolean(user), retry: false });
  const courseHistory = trpc.course.state.useQuery(undefined, { enabled: Boolean(user), retry: false, refetchInterval: 30000, refetchOnWindowFocus: true });
  const courseDeliveryHistory = trpc.dashboard.courseDeliveryHistory.useQuery(undefined, { enabled: Boolean(user), retry: false });
  const recordCourseDelivery = trpc.dashboard.recordCourseDelivery.useMutation({ onSuccess: () => void courseDeliveryHistory.refetch(), onError: (error) => toast.error("Delivery status could not be saved", { description: error.message }) });
  const requestOrganizationReview = trpc.course.requestOrganizationReview.useMutation({ onSuccess: () => { toast.success("Organization review request sent", { description: "The request is now pending review." }); if (deliveryEnrollmentId) recordCourseDelivery.mutate({ enrollmentId: deliveryEnrollmentId, step: "organization", status: "sent", organizationName: organizationName.trim(), recipientEmail: organizationEmail.trim() }); setDeliveryStep("share"); setOrganizationName(""); setOrganizationEmail(""); }, onError: (error) => toast.error("Could not request organization review", { description: error.message }) });
  const [compareWithId, setCompareWithId] = useState<number | null>(null);
  const [exportLens, setExportLens] = useState<RoleLens>("leadership");
  const [shareLink, setShareLink] = useState<string | null>(null);
  const [shareConsent, setShareConsent] = useState(false);
  const [shareExpiry, setShareExpiry] = useState<1 | 7 | 30>(7);
  const [shareLens, setShareLens] = useState<"leadership" | "teamDevelopment">("leadership");
  const [sharePurpose, setSharePurpose] = useState<"coaching" | "manager" | "">("");
  const [visibleDimensions, setVisibleDimensions] = useState<Record<string, boolean>>({});
  const [qaFixtureEnabled] = useState(() => import.meta.env.DEV && isQaFixtureEnabled(window.localStorage.getItem(QA_FIXTURE_STORAGE_KEY)));
  const [pngDownloading, setPngDownloading] = useState(false);
  const [deliveryEnrollmentId, setDeliveryEnrollmentId] = useState<number | null>(null);
  const [deliveryConsent, setDeliveryConsent] = useState(false);
  const [organizationName, setOrganizationName] = useState("");
  const [organizationEmail, setOrganizationEmail] = useState("");
  const [deliveryStep, setDeliveryStep] = useState<"idle" | "email" | "organization" | "share">("idle");
  type CourseDeliveryRecord = { enrollment: { id: number; name: string; email: string; courseSlug: string; updatedAt?: Date | string | null }; lessons?: Array<{ lessonId: string }>; quizAttempts?: Array<{ moduleId: string; score: number; passed: boolean }>; certificates: Array<{ id?: number; certificateNumber: string; courseTitle: string; fileUrl?: string | null; emailStatus?: string | null; emailedAt?: Date | string | null }>; stages: Array<{ stage: number; paymentStatus: string; paidAt?: Date | string | null; paystackReference?: string | null }> };
  const courseRecords = (courseHistory.data ?? []) as unknown as CourseDeliveryRecord[];
  const incompleteCourseRecords = courseRecords.filter((record) => record.stages?.some((stage) => stage.paymentStatus !== "paid"));
  const completedCourseRecords = courseRecords.filter((record) => record.certificates?.length && record.stages?.filter((stage) => stage.paymentStatus === "paid").length >= 4);
  const activeDelivery = completedCourseRecords.find((record) => record.enrollment.id === deliveryEnrollmentId) ?? completedCourseRecords[0];
  const activeCertificate = activeDelivery?.certificates?.[0];
  const previewMode = import.meta.env.DEV && (qaFixtureEnabled || new URLSearchParams(window.location.search).get("preview") === "versions");
  type DashboardVersion = { id: number; version?: string | null; overallScore?: number | null; overallBand?: string | null; createdAt: Date | string; paymentStatus: string; reportEmailStatus?: string | null; reportEmailSentAt?: Date | string | null; paystackReference?: string | null; dimensionScores?: Array<{ key: string; label: string; score: number }> };
  const previewVersions = reportComparisonPreviewHistory as unknown as DashboardVersion[];
  const displayHistory = (previewMode ? previewVersions : (history.data ?? [])) as DashboardVersion[];
  const allRecentActivity = displayHistory.filter((item) => activityFilter === "all" || (activityFilter === "unlocked" ? item.paymentStatus === "paid" : item.paymentStatus !== "paid"));
  const recentActivity = allRecentActivity.slice(0, activityLimit);
  const profileFields = [profile.data?.name, profile.data?.timezone, profile.data?.avatarUrl, profile.data?.notificationPreferences ? "preferences" : null];
  const profileCompletion = Math.round((profileFields.filter(Boolean).length / profileFields.length) * 100);
  const [showAssessmentHint, setShowAssessmentHint] = useState(() => window.localStorage.getItem("piq-new-assessment-hint-dismissed") !== "true");
  const [bookmarkVersion, setBookmarkVersion] = useState(0);
  const [bookmarkSearch, setBookmarkSearch] = useState("");
  const [bookmarkCourse, setBookmarkCourse] = useState("all");
  const dashboardBookmarks = useMemo(() => courseCatalog.flatMap((course) => { try { const saved = JSON.parse(window.localStorage.getItem(`piq-course-bookmarks-${course.slug}`) || "[]"); return (Array.isArray(saved) ? saved : []).flatMap((key: string) => { const [lessonId, kind, index] = key.split(":"); const lesson = course.modules.flatMap((module) => module.lessons).find((item) => item.id === lessonId); return lesson ? [{ key, course, lesson, kind, index }] : []; }); } catch { return []; } }), [bookmarkVersion]);
  const filteredBookmarks = dashboardBookmarks.filter((bookmark) => bookmarkCourse === "all" || bookmark.course.slug === bookmarkCourse).filter((bookmark) => `${bookmark.course.title} ${bookmark.lesson.title} ${bookmark.kind}`.toLowerCase().includes(bookmarkSearch.toLowerCase().trim()));
  const dashboardNotes = useMemo(() => courseCatalog.flatMap((course) => { try { const notes = JSON.parse(window.localStorage.getItem(`piq-course-notes-${course.slug}`) || "{}"); const summaries = new Map<string, string>(); course.modules.flatMap((module) => module.lessons).forEach((lesson) => { const summary = window.localStorage.getItem(`piq-course-summary-${course.slug}-${lesson.id}`); if (summary) summaries.set(lesson.id, summary); }); return Object.entries(notes).filter(([, value]) => typeof value === "string" && value.replace(/<[^>]+>/g, "").trim()).map(([lessonId, value]) => { const lesson = course.modules.flatMap((module) => module.lessons).find((item) => item.id === lessonId); return lesson ? { course, lesson, note: value as string, summary: summaries.get(lessonId) ?? "" } : null; }).filter((item): item is NonNullable<typeof item> => Boolean(item)); } catch { return []; } }), [bookmarkVersion]);
  const exportAllNotes = () => { const content = dashboardNotes.map((item) => `# ${item.course.title} — ${item.lesson.title}\n\n${item.note.replace(/<[^>]+>/g, "").replace(/&nbsp;/g, " ")}\n\n${item.summary ? `Summary:\n${item.summary}\n` : ""}`).join("\n---\n\n"); const url = URL.createObjectURL(new Blob([content || "No notes recorded."], { type: "text/markdown;charset=utf-8" })); const anchor = document.createElement("a"); anchor.href = url; anchor.download = "profound-iq-my-notes.md"; anchor.click(); URL.revokeObjectURL(url); toast.success("My Notes exported"); };
  const removeDashboardBookmark = (courseSlug: string, key: string) => { const storageKey = `piq-course-bookmarks-${courseSlug}`; try { const saved = JSON.parse(window.localStorage.getItem(storageKey) || "[]"); window.localStorage.setItem(storageKey, JSON.stringify((Array.isArray(saved) ? saved : []).filter((item) => item !== key))); setBookmarkVersion((version) => version + 1); toast.success("Bookmark removed"); } catch { toast.error("Could not remove bookmark"); } };
  const [auditAttemptId, setAuditAttemptId] = useState<number | "">("");
  const [auditEventType, setAuditEventType] = useState<"" | "consented" | "created" | "revoked">("");
  const paidVersions = previewMode ? [...previewVersions].reverse() : displayHistory.filter((item) => item.paymentStatus === "paid");
  const currentVersion = paidVersions[0];
  const trendData = [...paidVersions].reverse().map((item) => ({ version: item.version ?? `v${item.id}`, score: item.overallScore ?? 0, date: new Date(item.createdAt).toLocaleDateString(), ...Object.fromEntries((item.dimensionScores ?? []).map((dimension) => [dimension.key, dimension.score])) }));
  const trendDimensions = paidVersions[0]?.dimensionScores ?? [];
  const trendColors = ["#a27e2e", "#2f6f78", "#8b4f63", "#55705a", "#6d5b8d", "#b26836", "#3b6b9a", "#8b7650", "#6d7d83", "#9a4f4f"];
  const compareInput = useMemo(() => currentVersion && compareWithId ? { currentAttemptId: currentVersion.id, previousAttemptId: compareWithId } : undefined, [currentVersion, compareWithId]);
  const comparison = trpc.dashboard.compareReports.useQuery(compareInput!, { enabled: Boolean(compareInput) && !previewMode, retry: false });
  const comparisonData = previewMode ? reportComparisonPreview : comparison.data;
  const latestCareerPathReport = careerPathHistory.data?.[0]?.report as CareerPathReport | undefined;
  const shares = trpc.dashboard.reportShares.useQuery(undefined, { enabled: Boolean(user), retry: false });
  const auditInput = useMemo(() => ({ attemptId: auditAttemptId || undefined, eventType: auditEventType || undefined }), [auditAttemptId, auditEventType]);
  const shareAudit = trpc.dashboard.reportShareAudit.useQuery(auditInput, { enabled: Boolean(user), retry: false });
  const exportShareAudit = trpc.dashboard.exportShareAudit.useQuery(auditInput, { enabled: false, retry: false });
  const utils = trpc.useUtils();
  const downloadShareAudit = async () => { const result = await exportShareAudit.refetch(); if (!result.data) return; const blob = new Blob([result.data.csv], { type: "text/csv;charset=utf-8" }); const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = result.data.filename; anchor.click(); URL.revokeObjectURL(url); toast.success("Share audit downloaded"); };
  const resendReportEmail = trpc.dashboard.resendReportEmail.useMutation({
    onSuccess: () => { toast.success("Report email resent", { description: "A fresh PDF copy is on its way to your inbox." }); void utils.dashboard.mine.invalidate(); },
    onError: (error) => toast.error("Could not resend report email", { description: error.message }),
  });
  const careerPathDownload = trpc.careerPath.downloadReport.useMutation({ onError: (error) => toast.error("CareerPath download failed", { description: error.message }) });
  const buildLatestSubPathwayVisual = () => buildSubPathwayComparisonSvg({ rows: (latestCareerPathReport?.subPathways ?? []).map((item) => ({ label: item.label, score: item.score })), generatedAt: new Date().toLocaleDateString() });
  const downloadSubPathwayVisual = () => { const anchor = document.createElement("a"); anchor.href = svgToDownloadUrl(buildLatestSubPathwayVisual()); anchor.download = "profound-iq-careerpath-sub-pathways.svg"; document.body.appendChild(anchor); anchor.click(); anchor.remove(); toast.success("SVG coaching visual downloaded"); };
  const downloadSubPathwayPng = async () => { setPngDownloading(true); try { triggerDownload(await svgToPngBlob(buildLatestSubPathwayVisual()), "profound-iq-careerpath-sub-pathways.png"); toast.success("PNG coaching visual downloaded", { description: "A broadly compatible coaching image is ready to share." }); } catch (error) { toast.error("PNG export unavailable", { description: error instanceof Error ? error.message : "Please try the SVG download instead." }); } finally { setPngDownloading(false); } };
  const downloadCareerPathReport = async (reference: string) => {
    try {
      const result = await careerPathDownload.mutateAsync({ reference });
      const bytes = Uint8Array.from(atob(result.data), (character) => character.charCodeAt(0));
      const url = URL.createObjectURL(new Blob([bytes], { type: result.contentType }));
      const anchor = document.createElement("a"); anchor.href = url; anchor.download = result.filename; document.body.appendChild(anchor); anchor.click(); anchor.remove(); URL.revokeObjectURL(url);
      toast.success("CareerPath report downloaded");
    } catch { /* Mutation callback provides the user-facing error. */ }
  };
  const downloadReport = trpc.dashboard.downloadReport.useMutation({
    onError: (error) => toast.error("Report download failed", { description: error.message }),
  });
  const downloadScoreSummary = trpc.dashboard.downloadScoreSummary.useMutation({
    onError: (error) => toast.error("Score summary download failed", { description: error.message }),
  });
  const downloadScoreSummaryPdf = async () => {
    try {
      const result = await downloadScoreSummary.mutateAsync();
      const bytes = Uint8Array.from(atob(result.data), (character) => character.charCodeAt(0));
      const url = URL.createObjectURL(new Blob([bytes], { type: result.contentType }));
      const anchor = document.createElement("a"); anchor.href = url; anchor.download = result.filename; document.body.appendChild(anchor); anchor.click(); anchor.remove(); URL.revokeObjectURL(url);
      toast.success("Score summary downloaded", { description: "Your assessment score history is ready to review." });
    } catch { /* Mutation callback provides the user-facing error. */ }
  };
  useEffect(() => {
    if (!user || new URLSearchParams(window.location.search).get("download") !== "score-summary" || downloadScoreSummary.isPending) return;
    void downloadScoreSummaryPdf();
  }, [user]);
  const revokeShareLink = trpc.dashboard.revokeShareLink.useMutation({ onSuccess: () => { toast.success("Share link revoked"); void shares.refetch(); }, onError: (error) => toast.error("Could not revoke share link", { description: error.message }) });
  const createShareLink = trpc.dashboard.createShareLink.useMutation({
    onSuccess: (result) => { const url = `${window.location.origin}/shared-report?token=${encodeURIComponent(result.token)}`; setShareLink(url); setShareConsent(false); void navigator.clipboard?.writeText(url); toast.success("Private share link created", { description: "The seven-day link was copied to your clipboard." }); },
    onError: (error) => toast.error("Could not create share link", { description: error.message }),
  });

  const shareResultByEmail = async (attemptId: number) => {
    try {
      const result = await createShareLink.mutateAsync({ attemptId, expiresInDays: 7, consent: true, lens: "leadership", recipientPurpose: "coaching" });
      const url = `${window.location.origin}/shared-report?token=${encodeURIComponent(result.token)}`;
      window.location.href = `mailto:?subject=${encodeURIComponent("My Profound IQ assessment results")}&body=${encodeURIComponent(`I’m sharing my completed Profound IQ assessment results with you. This private link expires in 7 days: ${url}`)}`;
      toast.success("Email draft prepared", { description: "Your secure results link was added to a new email draft." });
    } catch { /* Mutation callback provides the user-facing error. */ }
  };

  const sendCourseCompletionImage = async (format: "native" | "svg" | "png") => {
    if (!activeDelivery || !activeCertificate) return;
    const svg = buildCourseCompletionShareSvg({ learnerName: activeDelivery.enrollment.name, courseTitle: activeCertificate.courseTitle, certificateNumber: activeCertificate.certificateNumber });
    try {
      const blob: Blob = format === "png" ? await svgToPngBlob(svg) : new Blob([svg], { type: "image/svg+xml" });
      const extension = format === "png" ? "png" : "svg";
      const mime = format === "png" ? "image/png" : "image/svg+xml";
      const file = new File([blob], `profound-iq-${activeCertificate.certificateNumber}.${extension}`, { type: mime });
      if (format === "native" && navigator.share && (!navigator.canShare || navigator.canShare({ files: [file] }))) { await navigator.share({ title: `${activeCertificate.courseTitle} completion`, text: `${activeDelivery.enrollment.name} completed ${activeCertificate.courseTitle} with Profound IQ Consulting.`, files: [file] }); toast.success("Completion image ready to share"); recordCourseDelivery.mutate({ enrollmentId: activeDelivery.enrollment.id, certificateId: activeCertificate.id, step: "social", status: "shared", metadata: { format: extension } }); }
      else { const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = file.name; document.body.appendChild(anchor); anchor.click(); anchor.remove(); URL.revokeObjectURL(url); toast.success(`${extension.toUpperCase()} completion image downloaded`, { description: "Upload the image to your preferred social platform." }); recordCourseDelivery.mutate({ enrollmentId: activeDelivery.enrollment.id, certificateId: activeCertificate.id, step: "social", status: "downloaded", metadata: { format: extension } }); }
      setDeliveryStep("share");
    } catch (error) { if ((error as DOMException)?.name !== "AbortError") toast.error("Could not prepare completion image", { description: "Please try again or download the certificate." }); }
  };
  const submitOrganizationRequest = () => { if (!activeDelivery || !deliveryConsent || !organizationName.trim() || !organizationEmail.trim()) { toast.error("Confirm consent and organization details first"); return; } void requestOrganizationReview.mutate({ enrollmentId: activeDelivery.enrollment.id, organizationName: organizationName.trim(), organizationEmail: organizationEmail.trim() }); };

  const handleResend = async (attemptId: number) => {
    try { await resendReportEmail.mutateAsync({ attemptId }); } catch { /* The mutation callback provides the user-facing error toast. */ }
  };

  const handleDownload = async (attemptId: number) => {
    try {
      const result = await downloadReport.mutateAsync({ attemptId, lens: exportLens });
      const bytes = Uint8Array.from(atob(result.data), (character) => character.charCodeAt(0));
      const url = URL.createObjectURL(new Blob([bytes], { type: result.contentType }));
      const anchor = document.createElement("a");
      anchor.href = url;
      anchor.download = result.filename;
      document.body.appendChild(anchor);
      anchor.click();
      anchor.remove();
      URL.revokeObjectURL(url);
      toast.success("Report downloaded", { description: "Your PDF is ready to review or share." });
    } catch {
      // The mutation callback provides the user-facing error toast.
    }
  };

  if (authLoading) return <LoadingState />;
  if (!user) return <AccessState />;

  return <div className="min-h-screen bg-[#f7f3e8] text-[#16243d]"><header className="border-b border-[#16243d]/15 bg-[#101d35] text-[#f7f3e8]"><div className="container flex flex-col gap-4 py-4 sm:flex-row sm:items-center sm:justify-between sm:py-5"><Link href="/" className="flex items-center gap-3"><BrandLogo context="my space" compactOnMobile /><span className="text-[11px] font-extrabold tracking-[.18em]">/ MY SPACE</span></Link><div className="flex w-full flex-wrap items-center gap-x-4 gap-y-2 sm:w-auto sm:justify-end"><button type="button" onClick={() => logout()} className="text-[10px] font-black uppercase tracking-[.16em] text-[#c1cad7] hover:text-[#c9a34e]">Sign out</button><Link href="/settings" className="text-[10px] font-black uppercase tracking-[.16em] text-[#c1cad7] hover:text-[#c9a34e]">Settings</Link><Link href="/" className="inline-flex items-center gap-2 text-[10px] font-black uppercase tracking-[.16em] text-[#c1cad7] hover:text-[#c9a34e]"><ArrowLeft size={14} /> Back to site</Link></div></div></header><main className="container py-10 sm:py-14 lg:py-20"><nav aria-label="Workspace navigation" className="mb-8 flex flex-wrap items-center gap-2 border border-[#16243d]/10 bg-white/55 p-2"><Link href="/dashboard" className="bg-[#16243d] px-3 py-2 text-[10px] font-black uppercase tracking-[.12em] text-[#f7f3e8]">Overview</Link><Link href="/assessment" className="border border-[#16243d]/15 px-3 py-2 text-[10px] font-black uppercase tracking-[.12em] hover:border-[#c9a34e]">Self-assessment</Link><Link href="/careerpath" className="border border-[#16243d]/15 px-3 py-2 text-[10px] font-black uppercase tracking-[.12em] hover:border-[#c9a34e]">CareerPath</Link><Link href="/settings" className="border border-[#16243d]/15 px-3 py-2 text-[10px] font-black uppercase tracking-[.12em] hover:border-[#c9a34e]">Settings</Link>{user.role === "admin" && <Link href="/admin" className="ml-auto border border-[#c9a34e] px-3 py-2 text-[10px] font-black uppercase tracking-[.12em] text-[#7d5e1e]">Admin observatory</Link>}</nav><div className="border-b border-[#16243d]/20 pb-8"><p className="eyebrow text-[#a27e2e]">Private workspace / personal development</p><p className="text-sm font-semibold text-[#657084]">Welcome back, {user.name?.split(" ")[0] || "there"}.</p><h1 className="display mt-3 text-5xl leading-none tracking-[-.04em] sm:text-6xl">Your <em className="font-normal text-[#a27e2e]">pathway</em>.</h1><div className="mt-6 max-w-2xl border-l-2 border-[#c9a34e] bg-white/55 p-4"><div className="flex items-center justify-between gap-4"><span className="text-[10px] font-black uppercase tracking-[.14em] text-[#657084]">Progress summary</span><span className="text-sm font-bold text-[#a27e2e]">{displayHistory.length ? `${Math.round((paidVersions.length / Math.max(displayHistory.length, 1)) * 100)}% unlocked` : "Ready to begin"}</span></div><div className="mt-3 h-2 overflow-hidden bg-[#16243d]/10"><div className="h-full bg-[#c9a34e] transition-all" style={{ width: `${displayHistory.length ? Math.min(100, Math.round((paidVersions.length / Math.max(displayHistory.length, 1)) * 100)) : 0}%` }} /></div><p className="mt-2 text-xs text-[#657084]">{paidVersions.length} paid report{paidVersions.length === 1 ? "" : "s"} available from {displayHistory.length} assessment{displayHistory.length === 1 ? "" : "s"}.</p></div><p className="mt-5 max-w-xl text-base leading-7 text-[#4a566a]">Review your Profound IQ assessment activity and return to any report unlocked through verified payment.</p></div>{history.isLoading && <div className="mt-10 flex items-center gap-3 border-l-2 border-[#c9a34e] bg-white/50 px-5 py-4 text-sm"><RefreshCw size={16} className="animate-spin text-[#a27e2e]" /> Loading your assessment history…</div>}{history.isError && <div className="mt-10 flex items-start gap-3 border-l-2 border-red-700 bg-red-50 px-5 py-4 text-sm text-red-900"><AlertCircle size={18} className="mt-0.5 shrink-0" /><div><p className="font-bold">Unable to load your history.</p><p className="mt-1">Please try again shortly.</p></div></div>}{(history.data || previewMode) && <><section className="mt-10 grid gap-4 sm:grid-cols-3"><Metric icon={FileText} label="Assessments" value={displayHistory.length} /><Metric icon={CheckCircle2} label="Reports unlocked" value={displayHistory.filter((item) => item.paymentStatus === "paid").length} accent /><Metric icon={Clock3} label="Pending payment" value={displayHistory.filter((item) => item.paymentStatus !== "paid").length} /></section><section className="mt-10 border border-[#c9a34e]/55 bg-[#fffaf0] p-5 sm:p-6"><div className="flex flex-col justify-between gap-4 border-b border-[#16243d]/10 pb-5 sm:flex-row sm:items-end"><div><p className="eyebrow text-[#a27e2e]">Course investment</p><h2 className="display mt-2 text-2xl">Track your access stage.</h2><p className="mt-2 max-w-2xl text-sm leading-6 text-[#657084]">Every professional course is KES {COURSE_PRICE_KES.toLocaleString()}, released through four verified KES {COURSE_STAGE_AMOUNT_KES.toLocaleString()} stages. Resume an incomplete enrollment whenever you are ready.</p></div><Link href="/courses" className="inline-flex shrink-0 items-center gap-2 border border-[#16243d]/25 px-3 py-2 text-[10px] font-black uppercase tracking-[.1em] hover:border-[#c9a34e]">Browse courses <ArrowLeft size={13} className="rotate-180" /></Link></div>{courseHistory.isLoading ? <div className="mt-5 flex items-center gap-2 text-sm text-[#657084]"><RefreshCw size={15} className="animate-spin text-[#a27e2e]" /> Loading course enrollments…</div> : incompleteCourseRecords.length ? <div className="mt-5 grid gap-4 lg:grid-cols-2">{incompleteCourseRecords.map((record) => { const course = courseCatalog.find((item) => item.slug === record.enrollment.courseSlug); const rollup = summarizeCourseEnrollment({ stages: record.stages, lessonsCompleted: record.lessons?.length, moduleCount: course?.modules.length }); return <article key={record.enrollment.id} className="border border-[#16243d]/12 bg-white/70 p-5"><div className="flex items-start justify-between gap-4"><div><p className="text-[10px] font-black uppercase tracking-[.12em] text-[#a27e2e]">Incomplete enrollment</p><h3 className="display mt-2 text-2xl">{course?.title ?? record.enrollment.courseSlug}</h3></div><span className="whitespace-nowrap text-xs font-bold text-[#7d5e1e]">{rollup.paidStages}/{rollup.totalStages} paid</span></div><div className="mt-5 h-2 overflow-hidden bg-[#16243d]/10"><div className="h-full bg-[#c9a34e] transition-all" style={{ width: `${rollup.paymentPercent}%` }} /></div><div className="mt-3 flex flex-wrap justify-between gap-2 text-xs text-[#657084]"><span>KES {rollup.paidAmountKes.toLocaleString()} paid</span><span>KES {rollup.remainingAmountKes.toLocaleString()} remaining</span></div><div className="mt-5 grid gap-2 sm:grid-cols-4">{[1, 2, 3, 4].map((stage) => <div key={stage} className={`border p-3 text-[10px] font-black uppercase tracking-[.08em] ${stage <= rollup.paidStages ? "border-[#c9a34e] bg-[#ead9ae]/50 text-[#7d5e1e]" : stage === rollup.nextStage ? "border-[#16243d]/35 bg-white text-[#16243d]" : "border-[#16243d]/10 text-[#8d96a3]"}`}><span className="block">Stage {stage}</span><span className="mt-1 block font-medium normal-case tracking-normal">{stage <= rollup.paidStages ? "Verified" : stage === rollup.nextStage ? "Next" : "Locked"}</span></div>)}</div><div className="mt-5 flex flex-wrap items-center justify-between gap-3 border-t border-[#16243d]/10 pt-4"><p className="text-xs text-[#657084]">{rollup.completedModules} of {course?.modules.length ?? 10} modules · {rollup.learningPercent}% learning progress</p><Link href={`/courses/${record.enrollment.courseSlug}`} className="inline-flex items-center gap-2 bg-[#16243d] px-4 py-3 text-[10px] font-black uppercase tracking-[.1em] text-[#f7f3e8]">Resume payment <ArrowLeft size={13} className="rotate-180" /></Link></div></article>; })}</div> : <div className="mt-5 flex flex-col justify-between gap-4 border border-dashed border-[#16243d]/20 bg-white/55 p-5 sm:flex-row sm:items-center"><div><p className="text-sm font-bold">No incomplete course enrollments.</p><p className="mt-1 text-xs leading-5 text-[#657084]">Your staged payment progress will appear here after you begin a course enrollment.</p></div><Link href="/courses" className="inline-flex shrink-0 items-center gap-2 border border-[#16243d]/25 px-4 py-3 text-[10px] font-black uppercase tracking-[.1em] hover:border-[#c9a34e]">Explore courses <ArrowLeft size={13} className="rotate-180" /></Link></div>}</section><section className="mt-10 border border-[#16243d]/15 bg-white/45 p-5 sm:p-6"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="eyebrow text-[#a27e2e]">Profile completion</p><h2 className="display mt-2 text-2xl">Make your workspace yours.</h2><p className="mt-2 text-sm text-[#657084]">Complete your profile to keep account settings and notifications ready.</p></div><div className="min-w-48"><div className="flex justify-between text-[10px] font-black uppercase tracking-[.12em] text-[#657084]"><span>{profileCompletion}% complete</span><button type="button" onClick={() => setProfileModalOpen(true)} className="text-[#a27e2e] underline-offset-4 hover:underline">Complete profile</button></div><div className="mt-2 h-2 bg-[#16243d]/10"><div className="h-full bg-[#c9a34e] transition-all" style={{ width: `${profileCompletion}%` }} /></div></div></div><div className="mt-10 flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="eyebrow text-[#a27e2e]">Recent activity</p><h2 className="display mt-2 text-2xl">Your latest movement.</h2></div><div className="flex items-center gap-3"><span className="text-xs text-[#657084]">Completed work and unlocked reports</span><select value={activityFilter} onChange={(event) => setActivityFilter(event.target.value as typeof activityFilter)} aria-label="Filter recent activity" className="border border-[#16243d]/20 bg-[#f7f3e8] px-2 py-2 text-xs"><option value="all">All activity</option><option value="completed">Assessments</option><option value="unlocked">Unlocked reports</option></select></div></div>{recentActivity.length === 0 ? <p className="mt-5 text-sm text-[#657084]">Your latest completed assessments and unlocked reports will appear here.</p> : <div className="mt-5 grid gap-3 sm:grid-cols-2">{recentActivity.map((item) => <Link key={item.id} href={item.paymentStatus === "paid" ? `/assessment?attemptId=${item.id}` : "/assessment"} className="group border border-[#16243d]/10 bg-[#f7f3e8] p-4 transition hover:-translate-y-0.5 hover:border-[#c9a34e]"><div className="flex items-start justify-between gap-3"><div><p className="text-[10px] font-black uppercase tracking-[.12em] text-[#657084]">{item.paymentStatus === "paid" ? "Report unlocked" : "Assessment started"}</p><p className="mt-2 text-sm font-bold">{item.version ?? `Assessment #${item.id}`}</p></div><span className={`h-2 w-2 rounded-full ${item.paymentStatus === "paid" ? "bg-emerald-600" : "bg-[#c9a34e]"}`} /></div><p className="mt-3 text-xs text-[#657084]">{new Date(item.createdAt).toLocaleDateString()} · {item.paymentStatus === "paid" ? `${item.overallScore ?? 0}/100 available` : "Payment pending"}</p>{item.paymentStatus === "paid" && <div className="mt-4 flex flex-wrap gap-2"><button type="button" onClick={(event) => { event.preventDefault(); event.stopPropagation(); void handleDownload(item.id); }} disabled={downloadReport.isPending} className="inline-flex items-center gap-2 border border-[#16243d]/20 px-3 py-2 text-[10px] font-black uppercase tracking-[.1em] text-[#7d5e1e] hover:border-[#c9a34e] disabled:cursor-wait disabled:opacity-60">{downloadReport.isPending ? <Loader2 size={13} className="animate-spin" /> : <Download size={13} />} {downloadReport.isPending ? "Preparing…" : "Export PDF"}</button><button type="button" onClick={(event) => { event.preventDefault(); event.stopPropagation(); void shareResultByEmail(item.id); }} disabled={createShareLink.isPending} className="inline-flex items-center gap-2 border border-[#16243d]/20 px-3 py-2 text-[10px] font-black uppercase tracking-[.1em] text-[#7d5e1e] hover:border-[#c9a34e] disabled:cursor-wait disabled:opacity-60"><Mail size={13} /> {createShareLink.isPending ? "Preparing…" : "Share by email"}</button></div>}</Link>)}</div>}{allRecentActivity.length > recentActivity.length && <button type="button" onClick={() => setActivityLimit((current) => current + 4)} className="mt-5 border border-[#16243d]/25 px-4 py-3 text-[10px] font-black uppercase tracking-[.12em] text-[#16243d] hover:border-[#c9a34e]">Load more activity</button>}</section><section className="mt-10 border border-[#16243d]/15 bg-white/45 p-5 sm:p-6"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="eyebrow text-[#a27e2e]">Course recommendations</p><h2 className="display mt-2 text-2xl">A pathway shaped by your assessment.</h2><p className="mt-2 max-w-2xl text-sm leading-6 text-[#657084]">These suggestions use your latest unlocked self-assessment signals to prioritize a practical next step. They are guidance, not a fixed label.</p></div>{recommendations.data?.basedOn && <span className="text-xs text-[#657084]">Based on {recommendations.data.basedOn.overallScore ?? 0}/100 · {new Date(recommendations.data.basedOn.completedAt).toLocaleDateString()}</span>}</div>{recommendations.isLoading ? <div className="mt-5 flex items-center gap-2 text-sm text-[#657084]"><RefreshCw size={15} className="animate-spin text-[#a27e2e]" /> Reading your assessment signals…</div> : recommendations.data?.recommendations?.length ? <div className="mt-6 grid gap-4 lg:grid-cols-3">{recommendations.data.recommendations.map((item, index) => <article key={item.course.slug} className="border border-[#16243d]/12 bg-[#f7f3e8] p-5 transition hover:-translate-y-0.5 hover:border-[#c9a34e]"><div className="flex items-start justify-between gap-3"><span className="text-[10px] font-black uppercase tracking-[.14em] text-[#a27e2e]">Priority {index + 1}</span><span className="text-xs font-bold text-[#7d5e1e]">{item.fitScore}% fit signal</span></div><h3 className="display mt-3 text-2xl">{item.course.title}</h3><p className="mt-2 text-sm font-semibold text-[#4a566a]">{item.course.strapline}</p><p className="mt-3 text-xs leading-6 text-[#657084]">{item.rationale}</p><div className="mt-4 flex flex-wrap gap-2">{item.matchedSignals.map((signal) => <span key={signal.key} className="border border-[#c9a34e]/60 bg-[#fffaf0] px-2 py-1 text-[10px] font-black uppercase tracking-[.08em] text-[#7d5e1e]">{signal.label} · {signal.score}</span>)}</div><Link href={`/courses/${item.course.slug}`} className="mt-5 inline-flex border border-[#16243d]/25 px-3 py-2 text-[10px] font-black uppercase tracking-[.1em] hover:border-[#c9a34e]">Explore course →</Link></article>)}</div> : <div className="mt-5 border-l-2 border-[#c9a34e] bg-[#fffaf0] p-4 text-sm leading-6 text-[#657084]"><p className="font-semibold text-[#16243d]">Complete and unlock your self-assessment to receive course recommendations.</p><p className="mt-1">Your recommendations will connect your strongest signals with a relevant learning pathway while keeping your report private.</p><Link href="/assessment" className="mt-3 inline-flex text-[10px] font-black uppercase tracking-[.1em] text-[#7d5e1e] underline-offset-4 hover:underline">Start self-assessment →</Link></div>}</section><section className="mt-10 border border-[#c9a34e]/50 bg-[#16243d] p-5 text-[#f7f3e8] sm:p-6"><p className="eyebrow text-[#c9a34e]">Recommended next step</p><h2 className="display mt-2 text-2xl">A useful signal to explore.</h2><p className="mt-3 max-w-2xl text-sm leading-6 text-[#c1cad7]">Based on your profile setup and current workspace activity, choose the pathway that best matches what you want to develop next.</p><div className="mt-5 grid gap-3 sm:grid-cols-2"><Link href="/assessment" className="border border-[#c9a34e]/60 bg-[#f7f3e8] p-4 text-[#16243d] transition hover:-translate-y-0.5"><p className="text-[10px] font-black uppercase tracking-[.12em] text-[#a27e2e]">Recommended for you</p><p className="mt-2 text-sm font-bold">Self-assessment refresh</p><p className="mt-1 text-xs text-[#657084]">Revisit your strengths and create a new paid report version.</p><button type="button" onClick={() => toast.info("Why this is recommended", { description: profile.data?.avatarUrl ? "Your profile is complete enough to support a focused refresh of your existing development signal." : "Completing your profile helps us keep this recommendation relevant to your development context." })} className="mt-3 text-[10px] font-black uppercase tracking-[.1em] text-[#7d5e1e] underline-offset-4 hover:underline">View details</button></Link><Link href="/careerpath" className="border border-white/20 p-4 transition hover:-translate-y-0.5"><p className="text-[10px] font-black uppercase tracking-[.12em] text-[#c9a34e]">Explore next</p><p className="mt-2 text-sm font-bold">CareerPath fit assessment</p><p className="mt-1 text-xs text-[#c1cad7]">Translate your profile signals into pathway possibilities.</p></Link></div></section><section className="mt-10 border border-[#c9a34e] bg-[#16243d] p-5 text-[#f7f3e8] sm:p-6"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="eyebrow text-[#c9a34e]">Completion delivery queue</p><h2 className="display mt-2 text-2xl">Move your milestone outward.</h2><p className="mt-2 max-w-2xl text-sm leading-6 text-[#c1cad7]">Completed courses refresh automatically here. Choose each outbound step deliberately: email confirmation, organization review request, then a shareable achievement image.</p></div><RefreshCw size={18} className={courseHistory.isFetching ? "animate-spin text-[#c9a34e]" : "text-[#c9a34e]"} aria-label="Course completion status refreshes automatically" /></div>{completedCourseRecords.length === 0 ? <p className="mt-6 border border-white/15 p-4 text-sm leading-6 text-[#c1cad7]">Finish a course and receive its certificate to unlock this delivery queue.</p> : <><div className="mt-6 flex flex-wrap gap-2">{completedCourseRecords.map((record) => <button key={record.enrollment.id} type="button" onClick={() => { setDeliveryEnrollmentId(record.enrollment.id); setDeliveryStep("idle"); setDeliveryConsent(false); }} className={`border px-3 py-2 text-left text-[10px] font-black uppercase tracking-[.1em] ${activeDelivery?.enrollment.id === record.enrollment.id ? "border-[#c9a34e] bg-[#c9a34e] text-[#16243d]" : "border-white/20 text-[#c1cad7] hover:border-[#c9a34e]"}`}>{record.certificates[0]?.courseTitle ?? record.enrollment.courseSlug}</button>)}</div>{activeDelivery && activeCertificate && <div className="mt-6 border border-white/15 bg-white/5 p-4 sm:p-5"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-start"><div><p className="text-[10px] font-black uppercase tracking-[.14em] text-[#c9a34e]">{activeCertificate.courseTitle}</p><p className="mt-2 text-sm font-bold">Certificate {activeCertificate.certificateNumber}</p><p className="mt-1 text-xs text-[#c1cad7]">Prepared for {activeDelivery.enrollment.name} · {activeDelivery.enrollment.email}</p></div><span className="border border-emerald-400/50 px-2 py-1 text-[10px] font-black uppercase tracking-[.1em] text-emerald-200">Completed</span></div><div className="mt-5 grid gap-2 sm:grid-cols-3"><button type="button" onClick={() => setDeliveryStep("email")} className={`border px-3 py-3 text-left text-[10px] font-black uppercase tracking-[.1em] ${deliveryStep === "email" ? "border-[#c9a34e] bg-[#c9a34e] text-[#16243d]" : "border-white/20 text-[#c1cad7] hover:border-[#c9a34e]"}`}><span className="block">01 · Email</span><span className="mt-1 block normal-case tracking-normal opacity-75">{activeCertificate.emailStatus === "sent" || activeCertificate.emailedAt ? "Delivered" : "Pending delivery"}</span></button><button type="button" disabled={deliveryStep === "idle"} onClick={() => setDeliveryStep("organization")} className={`border px-3 py-3 text-left text-[10px] font-black uppercase tracking-[.1em] disabled:cursor-not-allowed disabled:opacity-40 ${deliveryStep === "organization" ? "border-[#c9a34e] bg-[#c9a34e] text-[#16243d]" : "border-white/20 text-[#c1cad7] hover:border-[#c9a34e]"}`}><span className="block">02 · Organization</span><span className="mt-1 block normal-case tracking-normal opacity-75">Request review</span></button><button type="button" disabled={deliveryStep === "idle"} onClick={() => setDeliveryStep("share")} className={`border px-3 py-3 text-left text-[10px] font-black uppercase tracking-[.1em] disabled:cursor-not-allowed disabled:opacity-40 ${deliveryStep === "share" ? "border-[#c9a34e] bg-[#c9a34e] text-[#16243d]" : "border-white/20 text-[#c1cad7] hover:border-[#c9a34e]"}`}><span className="block">03 · Social image</span><span className="mt-1 block normal-case tracking-normal opacity-75">Download or share</span></button></div>{deliveryStep === "email" && <div className="mt-5 border-l-2 border-[#c9a34e] bg-white/5 p-4 text-sm leading-6 text-[#c1cad7]"><p className="font-semibold text-[#f7f3e8]">Certificate email status: {activeCertificate.emailStatus === "sent" || activeCertificate.emailedAt ? "Delivered" : "Processing"}.</p><p className="mt-1">The certificate was generated for {activeDelivery.enrollment.email}. Continue only when you are ready to request organization review.</p><button type="button" onClick={() => setDeliveryStep("organization")} className="mt-3 border border-[#c9a34e] px-3 py-2 text-[10px] font-black uppercase tracking-[.1em] text-[#c9a34e]">Continue to organization</button></div>}{deliveryStep === "organization" && <div className="mt-5 grid gap-3 border-l-2 border-[#c9a34e] bg-white/5 p-4 sm:grid-cols-2"><label className="text-[10px] font-black uppercase tracking-[.12em] text-[#c1cad7]">Organization name<input value={organizationName} onChange={(event) => setOrganizationName(event.target.value)} className="mt-2 w-full border border-white/20 bg-transparent px-3 py-3 text-sm font-normal normal-case tracking-normal text-[#f7f3e8]" placeholder="Organization or school" /></label><label className="text-[10px] font-black uppercase tracking-[.12em] text-[#c1cad7]">Organization email<input type="email" value={organizationEmail} onChange={(event) => setOrganizationEmail(event.target.value)} className="mt-2 w-full border border-white/20 bg-transparent px-3 py-3 text-sm font-normal normal-case tracking-normal text-[#f7f3e8]" placeholder="reviewer@organization.org" /></label><label className="flex items-start gap-2 text-xs leading-5 text-[#c1cad7] sm:col-span-2"><input type="checkbox" checked={deliveryConsent} onChange={(event) => setDeliveryConsent(event.target.checked)} className="mt-1 accent-[#c9a34e]" />I consent to Profound IQ sending this organization a review request for this certificate. No report access is granted until the request is reviewed.</label><div className="sm:col-span-2"><button type="button" onClick={submitOrganizationRequest} disabled={requestOrganizationReview.isPending} className="border border-[#c9a34e] px-4 py-3 text-[10px] font-black uppercase tracking-[.1em] text-[#c9a34e] disabled:opacity-50">{requestOrganizationReview.isPending ? "Sending request…" : "Send review request"}</button></div></div>}{deliveryStep === "share" && <div className="mt-5 flex flex-col justify-between gap-4 border-l-2 border-[#c9a34e] bg-white/5 p-4 sm:flex-row sm:items-center"><div><p className="font-semibold text-[#f7f3e8]">Your branded achievement image is ready.</p><p className="mt-1 text-xs leading-5 text-[#c1cad7]">Use native sharing on supported mobile browsers or download the SVG and upload it anywhere.</p></div><button type="button" onClick={() => void sendCourseCompletionImage("native")} className="border border-[#c9a34e] px-4 py-3 text-[10px] font-black uppercase tracking-[.1em] text-[#c9a34e]">Share image</button><button type="button" onClick={() => void sendCourseCompletionImage("png")} className="border border-white/25 px-4 py-3 text-[10px] font-black uppercase tracking-[.1em] text-[#c1cad7] hover:border-[#c9a34e]">Download PNG</button><button type="button" onClick={() => void sendCourseCompletionImage("svg")} className="border border-white/25 px-4 py-3 text-[10px] font-black uppercase tracking-[.1em] text-[#c1cad7] hover:border-[#c9a34e]">Download SVG</button></div>}</div>}</>}</section><section className="mt-10 border border-[#16243d]/15 bg-white/45 p-5 sm:p-6"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="eyebrow text-[#a27e2e]">Delivery history</p><h2 className="display mt-2 text-2xl">Your outward trail.</h2><p className="mt-2 text-sm leading-6 text-[#657084]">Track learner email, organization-review, and social-image actions across devices.</p></div><span className="text-xs text-[#657084]">{courseDeliveryHistory.data?.length ?? 0} recorded action{(courseDeliveryHistory.data?.length ?? 0) === 1 ? "" : "s"}</span></div>{courseDeliveryHistory.isLoading ? <p className="mt-5 text-sm text-[#657084]">Loading delivery history…</p> : courseDeliveryHistory.data?.length ? <div className="mt-5 space-y-2">{courseDeliveryHistory.data.map((event) => <div key={event.id} className="flex flex-col justify-between gap-2 border border-[#16243d]/10 bg-[#f7f3e8] p-4 sm:flex-row sm:items-center"><div><p className="text-[10px] font-black uppercase tracking-[.12em] text-[#a27e2e]">{event.step} · {event.status}</p><p className="mt-1 text-xs text-[#657084]">{event.organizationName || event.recipientEmail || "Personal delivery"}</p></div><time className="text-xs text-[#657084]">{new Date(event.createdAt).toLocaleString()}</time></div>)}</div> : <p className="mt-5 border border-dashed border-[#16243d]/15 p-4 text-sm text-[#657084]">Your delivery actions will appear here after you send, request, download, or share a completed course result.</p>}</section><section className="mt-12"><p className="eyebrow text-[#a27e2e]">Report versions</p><h2 className="display mt-3 text-3xl">See your movement over time.</h2><p className="mt-3 max-w-2xl text-sm leading-6 text-[#657084]">Each paid assessment is preserved as a dated report version. Compare your latest result with an earlier version to discuss meaningful changes, not just scores.</p><div className="mt-5 flex flex-col gap-3 sm:flex-row sm:items-end"><label className="text-[10px] font-black uppercase tracking-[.12em] text-[#657084]">PDF lens<select value={exportLens} onChange={(event) => setExportLens(event.target.value as RoleLens)} className="mt-2 block w-full border border-[#16243d]/20 bg-[#f7f3e8] px-3 py-3 text-sm font-normal normal-case tracking-normal"><option value="leadership">Leadership</option><option value="careerTransition">Career transition</option><option value="teamDevelopment">Team development</option></select></label><label className="text-[10px] font-black uppercase tracking-[.12em] text-[#657084]">Share expires<select value={shareExpiry} onChange={(event) => setShareExpiry(Number(event.target.value) as 1 | 7 | 30)} className="mt-2 block w-full border border-[#16243d]/20 bg-[#f7f3e8] px-3 py-3 text-sm font-normal normal-case tracking-normal"><option value={1}>24 hours</option><option value={7}>7 days</option><option value={30}>30 days</option></select></label><label className="text-[10px] font-black uppercase tracking-[.12em] text-[#657084]">Shared lens<select value={shareLens} onChange={(event) => setShareLens(event.target.value as "leadership" | "teamDevelopment")} className="mt-2 block w-full border border-[#16243d]/20 bg-[#f7f3e8] px-3 py-3 text-sm font-normal normal-case tracking-normal"><option value="leadership">Leadership</option><option value="teamDevelopment">Team development</option></select></label><label className="text-[10px] font-black uppercase tracking-[.12em] text-[#657084]">Recipient purpose<select value={sharePurpose} onChange={(event) => setSharePurpose(event.target.value as "coaching" | "manager" | "")} className="mt-2 block w-full border border-[#16243d]/20 bg-[#f7f3e8] px-3 py-3 text-sm font-normal normal-case tracking-normal"><option value="">Choose optional purpose</option><option value="coaching">Coaching conversation</option><option value="manager">Manager conversation</option></select></label><label className="flex max-w-sm items-start gap-2 text-xs leading-5 text-[#657084] sm:col-span-2"><input type="checkbox" checked={shareConsent} onChange={(event) => setShareConsent(event.target.checked)} className="mt-1 accent-[#a27e2e]" />I consent to sharing this paid report with a coach or manager through a temporary, read-only link.</label>{shareLink && <p className="max-w-xl break-all text-xs leading-5 text-emerald-800">Link ready: {shareLink}</p>}{shareAudit.data && <div className="mt-4 w-full border-t border-[#16243d]/15 pt-4 sm:col-span-2"><div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><p className="text-[10px] font-black uppercase tracking-[.12em] text-[#657084]">Share-link audit history</p><p className="mt-1 text-xs text-[#657084]">Consent, creation, and revocation events stay visible only to you.</p></div><button type="button" onClick={downloadShareAudit} disabled={exportShareAudit.isFetching} className="border border-[#16243d]/20 px-3 py-2 text-[10px] font-black uppercase tracking-[.1em]">{exportShareAudit.isFetching ? "Preparing…" : "Download CSV"}</button></div><div className="mt-3 grid gap-2 sm:grid-cols-2"><select value={auditAttemptId} onChange={(event) => setAuditAttemptId(event.target.value ? Number(event.target.value) : "")} className="border border-[#16243d]/20 bg-[#f7f3e8] px-3 py-2 text-xs"><option value="">All report versions</option>{paidVersions.map((item) => <option key={item.id} value={item.id}>{item.version ?? `Version ${item.id}`}</option>)}</select><select value={auditEventType} onChange={(event) => setAuditEventType(event.target.value as "" | "consented" | "created" | "revoked")} className="border border-[#16243d]/20 bg-[#f7f3e8] px-3 py-2 text-xs"><option value="">All event types</option><option value="consented">Consent recorded</option><option value="created">Link created</option><option value="revoked">Access revoked</option></select></div><div className="mt-3 space-y-2">{shareAudit.data.map((event) => <div key={event.id} className="flex flex-col gap-1 border border-[#16243d]/10 px-3 py-2 text-xs sm:flex-row sm:items-center sm:justify-between"><span className="font-semibold capitalize">{event.eventType}</span><span className="text-[#657084]">{event.recipientPurpose ? `${event.recipientPurpose} · ` : ""}{new Date(event.createdAt).toLocaleString()}</span></div>)}</div>{shareAudit.data.length === 0 && <p className="mt-3 text-xs text-[#657084]">No share events match these filters.</p>}</div>}{shares.data && shares.data.length > 0 && <div className="mt-4 w-full border-t border-[#16243d]/15 pt-4 sm:col-span-2"><p className="text-[10px] font-black uppercase tracking-[.12em] text-[#657084]">Active private links</p><div className="mt-3 space-y-2">{shares.data.map((share) => <div key={share.id} className="flex flex-col gap-2 border border-[#16243d]/10 px-3 py-3 text-xs sm:flex-row sm:items-center sm:justify-between"><span>{share.revokedAt ? "Revoked" : `Expires ${new Date(share.expiresAt).toLocaleDateString()}`}</span>{!share.revokedAt && <button type="button" onClick={() => revokeShareLink.mutate({ shareId: share.id })} disabled={revokeShareLink.isPending} className="self-start text-[10px] font-black uppercase tracking-[.12em] text-red-800 sm:self-auto">Revoke access</button>}</div>)}</div></div>}</div>{paidVersions.length > 1 && <div className="mt-6 border border-[#16243d]/15 bg-white/45 p-5 sm:p-6"><div className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><label className="text-[10px] font-black uppercase tracking-[.12em] text-[#657084]">Compare latest with<select value={compareWithId ?? ""} onChange={(event) => setCompareWithId(event.target.value ? Number(event.target.value) : null)} className="mt-2 block w-full border border-[#16243d]/20 bg-[#f7f3e8] px-3 py-3 text-sm font-normal normal-case tracking-normal outline-none focus:border-[#a27e2e]"><option value="">Choose an earlier version</option>{paidVersions.slice(1).map((item) => <option key={item.id} value={item.id}>{item.version} · {new Date(item.createdAt).toLocaleDateString()}</option>)}</select></label>{comparisonData && <p className={`text-sm font-bold ${comparisonData.comparison.scoreDelta >= 0 ? "text-emerald-800" : "text-red-800"}`}>{comparisonData.comparison.scoreDelta >= 0 ? "+" : ""}{comparisonData.comparison.scoreDelta} points overall</p>}</div>{comparisonData && <div className="mt-6 h-56 w-full"><p className="mb-3 text-[10px] font-black uppercase tracking-[.12em] text-[#657084]">Overall score trend</p><div className="mb-4 flex flex-wrap items-center gap-2"><button type="button" onClick={() => setVisibleDimensions(Object.fromEntries(trendDimensions.map((dimension) => [dimension.key, true])))} className="border border-[#16243d]/25 px-2 py-1 text-[9px] font-black uppercase tracking-[.08em] text-[#16243d]">Show all</button><button type="button" onClick={() => setVisibleDimensions(Object.fromEntries(trendDimensions.map((dimension) => [dimension.key, false])))} className="border border-[#16243d]/15 px-2 py-1 text-[9px] font-black uppercase tracking-[.08em] text-[#657084]">Hide all</button>{trendDimensions.map((dimension) => <button key={dimension.key} type="button" onClick={() => setVisibleDimensions((current) => ({ ...current, [dimension.key]: !(current[dimension.key] ?? true) }))} className={`border px-2 py-1 text-[9px] font-black uppercase tracking-[.08em] ${visibleDimensions[dimension.key] === false ? "border-[#16243d]/15 text-[#9aa2ad] line-through" : "border-[#a27e2e]/50 text-[#7d5e1e]"}`}>{dimension.label}</button>)}</div><ResponsiveContainer width="100%" height="100%"><LineChart data={trendData} margin={{ top: 4, right: 8, bottom: 4, left: -20 }}><XAxis dataKey="version" tick={{ fontSize: 10 }} /><YAxis domain={[0, 100]} tick={{ fontSize: 10 }} /><Tooltip formatter={(value) => [`${value} / 100`, "Score"]} labelFormatter={(label) => `${label} · ${trendData.find((item) => item.version === label)?.date ?? ""}`} /><Line type="monotone" dataKey="score" name="Overall" stroke="#16243d" strokeWidth={3} dot={{ r: 4, fill: "#16243d" }} activeDot={{ r: 6 }} />{trendDimensions.filter((dimension) => visibleDimensions[dimension.key] !== false).map((dimension, index) => <Line key={dimension.key} type="monotone" dataKey={dimension.key} name={dimension.label} stroke={trendColors[index % trendColors.length]} strokeWidth={1.6} dot={false} activeDot={{ r: 4 }} />)}</LineChart></ResponsiveContainer></div>}{comparisonData && <div className="mt-6 grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{comparisonData.comparison.dimensions.map((dimension) => <div key={dimension.key} className="border-t border-[#16243d]/15 pt-3"><p className="text-xs font-bold">{dimension.label}</p><p className="mt-2 text-xs text-[#657084]">{dimension.previousScore} → {dimension.currentScore} <span className={`font-black ${dimension.delta >= 0 ? "text-emerald-800" : "text-red-800"}`}>({dimension.delta >= 0 ? "+" : ""}{dimension.delta})</span></p></div>)}</div>}</div>} {paidVersions.length <= 1 && <div className="mt-6 border border-dashed border-[#16243d]/25 p-6 text-sm leading-6 text-[#657084]">Complete another paid assessment to create a second report version for comparison.</div>}</section><section className="mt-12"><p className="eyebrow text-[#a27e2e]">Your assessment history</p><h2 className="display mt-3 text-3xl">Keep the signal moving.</h2>{displayHistory.length === 0 ? <div className="mt-6 border border-dashed border-[#16243d]/25 p-8 text-sm leading-6 text-[#657084]">No assessment is linked to {user.email}. Start the KES 200 self-assessment to create your first development signal.</div> : <div className="mt-6 space-y-4">{displayHistory.map((item) => <article key={item.id} className="border border-[#16243d]/15 bg-white/45 p-5 sm:p-6"><div className="flex flex-col justify-between gap-5 sm:flex-row sm:items-center"><div><p className="text-xs font-black uppercase tracking-[.14em] text-[#657084]">{item.version ?? `Version ${item.id}`} · Assessment #{item.id} · {new Date(item.createdAt).toLocaleDateString()}</p>{item.paymentStatus === "paid" ? <div className="mt-3 flex items-baseline gap-3"><span className="display text-4xl text-[#a27e2e]">{item.overallScore}</span><span className="text-sm text-[#657084]">{item.overallBand}</span></div> : <p className="mt-3 text-sm font-semibold text-[#657084]">Report locked until payment is verified.</p>}</div><div className="flex flex-wrap items-center gap-3">{item.paymentStatus === "paid" ? <span className="inline-flex items-center gap-2 text-xs font-black uppercase tracking-[.1em] text-emerald-800"><span className="h-2 w-2 rounded-full bg-emerald-600" /> Paid</span> : <span className="inline-flex items-center gap-2 text-xs font-black uppercase tracking-[.1em] text-[#a27e2e]"><span className="h-2 w-2 rounded-full bg-[#c9a34e]" /> Pending</span>}{item.paymentStatus === "paid" && <><ReportEmailStatus status={item.reportEmailStatus} sentAt={item.reportEmailSentAt} />{item.reportEmailStatus !== "sent" && item.reportEmailStatus !== "sending" && <button type="button" onClick={() => handleResend(item.id)} disabled={resendReportEmail.isPending} className="inline-flex items-center gap-2 border border-[#a27e2e]/40 px-3 py-2 text-[10px] font-black uppercase tracking-[.12em] text-[#7d5e1e] disabled:cursor-wait disabled:opacity-60" aria-label={`Resend PDF report email for assessment ${item.id}`}>{resendReportEmail.isPending ? <MailWarning size={13} className="animate-[spin_1.4s_linear_infinite] motion-reduce:animate-none" aria-hidden="true" /> : <MailWarning size={13} aria-hidden="true" />} {resendReportEmail.isPending ? "Resending…" : "Resend email"}</button>}</>}{item.paymentStatus === "paid" && <button type="button" onClick={() => createShareLink.mutate({ attemptId: item.id, expiresInDays: shareExpiry, consent: true, lens: shareLens, recipientPurpose: sharePurpose || undefined })} disabled={createShareLink.isPending || !shareConsent} className="inline-flex items-center gap-2 border border-[#a27e2e]/40 px-4 py-3 text-[10px] font-black uppercase tracking-[.14em] text-[#7d5e1e]">{createShareLink.isPending ? "Creating…" : "Share privately"}</button>}{item.paymentStatus === "paid" && item.paystackReference && <><Link href={`/assessment?reference=${item.paystackReference}`} className="inline-flex items-center gap-2 bg-[#16243d] px-4 py-3 text-[10px] font-black uppercase tracking-[.14em] text-[#f7f3e8]">View report <ArrowLeft className="rotate-180" size={14} /></Link><button type="button" onClick={() => handleDownload(item.id)} disabled={downloadReport.isPending} className="inline-flex items-center gap-2 border border-[#16243d]/25 px-4 py-3 text-[10px] font-black uppercase tracking-[.14em] disabled:cursor-wait disabled:opacity-60" aria-label={`Download PDF report for assessment ${item.id}`}>{downloadReport.isPending ? <Loader2 size={14} className="animate-spin" /> : <Download size={14} />} {downloadReport.isPending ? "Preparing…" : "Download PDF"}</button></>}</div></div></article>)}</div>}</section><div className="mt-10 flex items-start gap-3 border-l-2 border-[#c9a34e] bg-[#16243d] p-5 text-sm leading-6 text-[#c1cad7]"><ShieldCheck size={18} className="mt-0.5 shrink-0 text-[#c9a34e]" /><p><strong className="text-[#f7f3e8]">Your privacy.</strong> This dashboard is scoped to your authenticated account email. It does not display raw answers to other users or expose your data publicly.</p></div></>}<section className="mt-12 border-t border-[#16243d]/20 pt-10"><div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><p className="eyebrow text-[#a27e2e]">Professional courses</p><h2 className="display mt-3 text-3xl">Your learning and certificates.</h2><p className="mt-2 max-w-2xl text-sm leading-6 text-[#657084]">Resume enrolled courses, review verified payment stages, and re-download certificates whenever you need a professional copy.</p></div><Link href="/#courses" className="inline-flex items-center gap-2 border border-[#16243d]/25 px-4 py-3 text-[10px] font-black uppercase tracking-[.12em]">Explore courses <ArrowLeft className="rotate-180" size={14} /></Link></div>{courseHistory.isLoading && <div className="mt-6 flex items-center gap-2 text-sm text-[#657084]"><RefreshCw className="animate-spin text-[#a27e2e]" size={16} /> Loading course history…</div>}{courseHistory.data && (courseHistory.data.length ? <div className="mt-6 grid gap-4 lg:grid-cols-2">{courseHistory.data.map((item) => { const paidStages = item.stages.filter((stage) => stage.paymentStatus === "paid").length; const latestCertificate = item.certificates[0]; return <article key={item.enrollment.id} className="border border-[#16243d]/15 bg-white/45 p-5"><div className="flex items-start justify-between gap-4"><div><p className="text-[10px] font-black uppercase tracking-[.14em] text-[#a27e2e]">Course enrollment</p><h3 className="display mt-2 text-2xl">{item.enrollment.courseSlug.replace(/-/g, " ")}</h3></div><span className="text-[10px] font-black uppercase tracking-[.12em] text-[#a27e2e]">{paidStages}/4 stages paid</span></div><div className="mt-5 h-2 bg-[#16243d]/10"><div className="h-2 bg-[#c9a34e]" style={{ width: `${Math.round((item.lessons.length / 70) * 70 + (new Set(item.quizAttempts.filter((attempt) => attempt.passed).map((attempt) => attempt.moduleId)).size / 10) * 30)}%` }} /></div><p className="mt-3 text-xs text-[#657084]">{item.lessons.length} of 70 lessons completed · {new Set(item.quizAttempts.filter((attempt) => attempt.passed).map((attempt) => attempt.moduleId)).size} of 10 module quizzes passed</p><div className="mt-5 flex flex-wrap items-center gap-3">{latestCertificate?.fileUrl ? <a href={latestCertificate.fileUrl} target="_blank" rel="noreferrer" className="inline-flex items-center gap-2 bg-[#16243d] px-3 py-2 text-[10px] font-black uppercase tracking-[.1em] text-[#f7f3e8]"><Download size={13} /> Download certificate</a> : <span className="inline-flex items-center gap-2 text-xs text-[#657084]"><Clock3 size={13} /> Certificate unlocks after completion</span>}<Link href={`/courses/${item.enrollment.courseSlug}`} className="inline-flex items-center gap-2 border-b border-[#16243d]/25 pb-1 text-[10px] font-black uppercase tracking-[.1em] text-[#a27e2e]">Open course <ArrowLeft className="rotate-180" size={13} /></Link></div></article>; })}</div> : <div className="mt-6 border border-dashed border-[#16243d]/20 bg-white/35 p-6 text-sm text-[#657084]">No course enrollments yet. Choose a professional course to begin your learning path.</div>)}</section><section className="mt-12 border-t border-[#16243d]/20 pt-10"><p className="eyebrow text-[#a27e2e]">CareerPath / talent fit</p><div className="mt-3 flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><h2 className="display text-3xl">Your pathway history.</h2><p className="mt-2 max-w-xl text-sm leading-6 text-[#657084]">Paid CareerPath reports are preserved here so you can revisit your sub-pathway signals and download a branded copy when needed.</p></div><Link href="/careerpath" className="inline-flex items-center gap-2 border border-[#16243d]/25 px-4 py-3 text-[10px] font-black uppercase tracking-[.12em]">Start another CareerPath <ArrowLeft className="rotate-180" size={14} /></Link></div>{careerPathHistory.isLoading && <div className="mt-6 flex items-center gap-2 text-sm text-[#657084]"><RefreshCw className="animate-spin text-[#a27e2e]" size={16} /> Loading CareerPath history…</div>}{careerPathHistory.isError && <p className="mt-6 border-l-2 border-red-700 bg-red-50 px-4 py-3 text-sm text-red-900">Unable to load CareerPath history right now.</p>}{careerPathHistory.data && (careerPathHistory.data.length ? <div className="mt-6 grid gap-4 lg:grid-cols-2">{careerPathHistory.data.map((item) => <article key={item.id} className="border border-[#16243d]/15 bg-white/45 p-5"><div className="flex items-start justify-between gap-4"><div><p className="text-[10px] font-black uppercase tracking-[.14em] text-[#a27e2e]">CareerPath report #{item.id}</p><p className="mt-2 text-sm font-bold">{new Date(item.createdAt).toLocaleDateString("en-KE", { year: "numeric", month: "long", day: "numeric" })}</p></div><span className={`text-[10px] font-black uppercase tracking-[.12em] ${item.paymentStatus === "paid" ? "text-emerald-800" : "text-[#a27e2e]"}`}>{item.paymentStatus === "paid" ? "Paid" : "Payment pending"}</span></div>{item.paymentStatus === "paid" && Boolean(item.report) && <><div className="mt-5 border-t border-[#16243d]/10 pt-4"><p className="text-[10px] font-black uppercase tracking-[.12em] text-[#657084]">Primary pathway</p><p className="mt-1 text-xl font-semibold text-[#a27e2e]">{(item.report as { primary?: { label: string; score: number } }).primary?.label ?? "CareerPath signal"} <span className="text-sm font-normal text-[#657084]">/ {(item.report as { primary?: { label: string; score: number } }).primary?.score ?? 0} / 100</span></p></div><div className="mt-4 flex flex-wrap items-center gap-3"><button type="button" onClick={() => item.paystackReference && downloadCareerPathReport(item.paystackReference)} disabled={!item.paystackReference || careerPathDownload.isPending} className="inline-flex items-center gap-2 bg-[#16243d] px-3 py-2 text-[10px] font-black uppercase tracking-[.1em] text-[#f7f3e8]">{careerPathDownload.isPending ? <Loader2 className="animate-spin" size={13} /> : <Download size={13} />} Download PDF</button><CoachingVisualPreview svg={buildLatestSubPathwayVisual()} pngLoading={pngDownloading} onDownloadSvg={downloadSubPathwayVisual} onDownloadPng={downloadSubPathwayPng} /><span className="inline-flex items-center gap-2 text-xs text-[#657084]"><Mail size={13} /> {item.reportEmailStatus === "sent" ? `Report emailed${item.reportEmailSentAt ? ` · ${new Date(item.reportEmailSentAt).toLocaleDateString()}` : ""}` : "Email preparing"}</span></div></>}</article>)}</div> : <div className="mt-6 border border-dashed border-[#16243d]/20 bg-white/35 p-6 text-sm text-[#657084]">No CareerPath reports yet. Complete the assessment to create your first learner pathway profile.</div>)}</section><section className="mt-10 border border-[#16243d]/15 bg-white/55 p-5 sm:p-8"><div className="flex flex-wrap items-end justify-between gap-3 border-b border-[#16243d]/15 pb-5"><div><p className="eyebrow text-[#a27e2e]">Saved for later</p><h2 className="display mt-2 text-3xl">My Bookmarks</h2></div><div className="flex flex-wrap gap-2"><input value={bookmarkSearch} onChange={(event) => setBookmarkSearch(event.target.value)} placeholder="Search saved lessons" aria-label="Search bookmarks" className="border border-[#16243d]/20 bg-[#f7f3e8] px-3 py-2 text-xs" /><select value={bookmarkCourse} onChange={(event) => setBookmarkCourse(event.target.value)} aria-label="Filter bookmarks by course" className="border border-[#16243d]/20 bg-[#f7f3e8] px-3 py-2 text-xs"><option value="all">All courses</option>{courseCatalog.map((course) => <option key={course.slug} value={course.slug}>{course.title}</option>)}</select><span className="self-center text-xs text-[#657084]">{filteredBookmarks.length} saved</span></div></div>{filteredBookmarks.length ? <div className="mt-5 grid gap-3">{filteredBookmarks.map((bookmark) => <article key={`${bookmark.course.slug}-${bookmark.key}`} className="flex flex-wrap items-center gap-4 border border-[#16243d]/10 bg-[#f7f3e8] p-4"><div className="grid h-10 w-10 shrink-0 place-items-center bg-[#16243d] text-[#c9a34e]">{bookmark.kind === "simulation" ? "S" : "§"}</div><div className="min-w-0 flex-1"><p className="text-[10px] font-black uppercase tracking-[.12em] text-[#a27e2e]">{bookmark.course.title} · {bookmark.kind === "simulation" ? "Decision simulation" : `Lesson section ${Number(bookmark.index) + 1}`}</p><p className="mt-1 truncate text-sm font-bold text-[#16243d]">{bookmark.lesson.title}</p></div><Link href={`/courses/${bookmark.course.slug}`} className="text-[10px] font-black uppercase tracking-[.1em] text-[#7d5e1e] hover:text-[#a27e2e]">Open lesson →</Link><button type="button" onClick={() => removeDashboardBookmark(bookmark.course.slug, bookmark.key)} className="text-[10px] font-black uppercase tracking-[.1em] text-[#657084] hover:text-red-700">Remove</button></article>)}</div> : <p className="mt-5 border border-dashed border-[#16243d]/15 p-5 text-sm leading-6 text-[#657084]">Save a lesson section or simulation in the interactive player and it will appear here for quick access.</p>}</section><section className="mt-10 border border-[#16243d]/15 bg-white/55 p-5 sm:p-8"><div className="flex flex-wrap items-end justify-between gap-3 border-b border-[#16243d]/15 pb-5"><div><p className="eyebrow text-[#a27e2e]">Study archive</p><h2 className="display mt-2 text-3xl">My Notes</h2><p className="mt-2 text-sm text-[#657084]">Review lesson takeaways and generated summaries in one place.</p></div><button type="button" onClick={exportAllNotes} disabled={!dashboardNotes.length} className="border border-[#16243d]/25 px-3 py-2 text-[10px] font-black uppercase tracking-[.1em] disabled:opacity-50">Export Markdown</button></div>{dashboardNotes.length ? <div className="mt-5 space-y-4">{dashboardNotes.map((item) => <article key={`${item.course.slug}-${item.lesson.id}`} className="border border-[#16243d]/10 bg-[#f7f3e8] p-4"><p className="text-[10px] font-black uppercase tracking-[.12em] text-[#a27e2e]">{item.course.title}</p><Link href={`/courses/${item.course.slug}`} className="mt-1 block text-sm font-bold text-[#16243d] underline-offset-4 hover:text-[#a27e2e] hover:underline">{item.lesson.title} →</Link><p className="mt-3 whitespace-pre-wrap text-xs leading-6 text-[#4a566a]">{item.note.replace(/<[^>]+>/g, "").replace(/&nbsp;/g, " ")}</p>{item.summary && <p className="mt-3 whitespace-pre-wrap border-l-2 border-[#c9a34e] bg-[#fffaf0] p-3 text-xs leading-5 text-[#7d5e1e]">{item.summary}</p>}</article>)}</div> : <p className="mt-5 border border-dashed border-[#16243d]/15 p-5 text-sm leading-6 text-[#657084]">Notes you save in a lesson player will be collected here.</p>}</section></main>{profileModalOpen && <div className="fixed inset-0 z-50 grid place-items-center bg-[#101d35]/75 p-4" role="presentation"><div role="dialog" aria-modal="true" aria-labelledby="profile-complete-title" className="w-full max-w-md border border-[#c9a34e] bg-[#f7f3e8] p-6 text-[#16243d] shadow-2xl sm:p-8"><div className="flex items-start justify-between gap-4"><div><p className="eyebrow text-[#a27e2e]">Workspace setup</p><h2 id="profile-complete-title" className="display mt-2 text-3xl">Complete your profile.</h2></div><button type="button" onClick={() => setProfileModalOpen(false)} className="text-xs font-black uppercase tracking-[.12em] text-[#657084]">Close</button></div><p className="mt-5 text-sm leading-7 text-[#4a566a]">Add the details below to make your workspace more personal and keep notifications relevant.</p><div className="mt-6 space-y-3">{!profile.data?.name && <Link href="/settings" onClick={() => setProfileModalOpen(false)} className="block border border-[#16243d]/15 bg-white/60 p-4 text-sm font-bold hover:border-[#c9a34e]">Add your full name <span className="float-right">→</span></Link>}{!profile.data?.timezone && <Link href="/settings" onClick={() => setProfileModalOpen(false)} className="block border border-[#16243d]/15 bg-white/60 p-4 text-sm font-bold hover:border-[#c9a34e]">Choose your timezone <span className="float-right">→</span></Link>}{!profile.data?.avatarUrl && <Link href="/settings" onClick={() => setProfileModalOpen(false)} className="block border border-[#16243d]/15 bg-white/60 p-4 text-sm font-bold hover:border-[#c9a34e]">Add a profile avatar <span className="float-right">→</span></Link>}{!profile.data?.notificationPreferences && <Link href="/settings" onClick={() => setProfileModalOpen(false)} className="block border border-[#16243d]/15 bg-white/60 p-4 text-sm font-bold hover:border-[#c9a34e]">Set notification preferences <span className="float-right">→</span></Link>}{profileCompletion === 100 && <p className="text-sm font-semibold text-emerald-800">Your profile is complete.</p>}</div></div></div>}<div className="fixed bottom-6 right-6 z-40 flex flex-col items-end gap-2"><div className={`max-w-xs border border-[#c9a34e] bg-[#fffaf0] p-3 text-xs leading-5 text-[#16243d] shadow-lg transition ${showAssessmentHint ? "opacity-100" : "pointer-events-none translate-y-2 opacity-0"}`} role="status">Start a fresh self-assessment whenever you want to explore a new development signal.<button type="button" onClick={() => { setShowAssessmentHint(false); window.localStorage.setItem("piq-new-assessment-hint-dismissed", "true"); }} className="ml-2 font-black uppercase tracking-[.08em] text-[#7d5e1e]">Dismiss</button></div><Link href="/assessment" className="inline-flex items-center gap-2 rounded-full bg-[#c9a34e] px-5 py-4 text-[10px] font-black uppercase tracking-[.12em] text-[#16243d] shadow-xl transition hover:-translate-y-0.5 hover:bg-[#d7b762] focus:outline-none focus-visible:ring-2 focus-visible:ring-[#16243d] focus-visible:ring-offset-2"><span className="text-lg leading-none">+</span> New self-assessment</Link></div></div>;
}

function ReportEmailStatus({ status, sentAt }: { status?: string | null; sentAt?: Date | string | null }) {
  const formattedSentAt = formatReportEmailSentAt(sentAt);
  if (status === "sent") return <span className="inline-flex flex-wrap items-center gap-2 text-xs font-black uppercase tracking-[.1em] text-emerald-800" title={formattedSentAt ? `Report email sent ${formattedSentAt}` : "Report email sent"}><MailCheck size={14} aria-hidden="true" /> Email sent{formattedSentAt && <span className="inline-flex items-center gap-1 font-medium normal-case tracking-normal text-[#657084]"><Mail size={12} aria-hidden="true" /> Last emailed {formattedSentAt}</span>}<span className="sr-only">{formattedSentAt ? `, last emailed ${formattedSentAt}` : ""}</span></span>;
  if (status === "sending") return <span className="inline-flex items-center gap-2 text-xs font-black uppercase tracking-[.1em] text-[#a27e2e]" title="Report email is being prepared"><Clock3 size={14} aria-hidden="true" /> Email in progress</span>;
  return <span className="inline-flex items-center gap-2 text-xs font-black uppercase tracking-[.1em] text-[#a27e2e]" title="Report email is pending and will be retried"><MailWarning size={14} aria-hidden="true" /> Email pending</span>;
}
function Metric({ icon: Icon, label, value, accent = false }: { icon: typeof FileText; label: string; value: number; accent?: boolean }) { return <div className={`border-t-2 ${accent ? "border-[#c9a34e]" : "border-[#16243d]/30"} bg-white/45 p-5`}><Icon size={18} className={accent ? "text-[#a27e2e]" : "text-[#657084]"} /><p className="mt-6 text-xs font-black uppercase tracking-[.14em] text-[#657084]">{label}</p><p className="display mt-2 text-4xl">{value}</p></div>; }
function LoadingState() { return <div className="grid min-h-screen place-items-center bg-[#f7f3e8] text-[#16243d]"><RefreshCw className="animate-spin text-[#a27e2e]" /></div>; }
function AccessState() { return <div className="grid min-h-screen place-items-center bg-[#f7f3e8] px-6 text-[#16243d]"><div className="max-w-md border-t-2 border-[#c9a34e] bg-white/50 p-8 text-center"><LockKeyhole className="mx-auto text-[#a27e2e]" /><h1 className="display mt-5 text-4xl">Sign in to continue</h1><p className="mt-4 text-sm leading-6 text-[#657084]">Your personal assessment history is private to your authenticated account.</p><div className="mt-7 flex flex-col justify-center gap-3 sm:flex-row"><button onClick={() => startLogin()} className="bg-[#16243d] px-5 py-4 text-[11px] font-black uppercase tracking-[.15em] text-[#f7f3e8]">Sign in →</button><Link href="/" className="border border-[#16243d]/25 px-5 py-4 text-[11px] font-black uppercase tracking-[.15em]">Return to site</Link></div></div></div>; }
